type FormState = 'idle' | 'sending' | 'sent' | 'error';

function ContactForm() {
  const [state, setState] = useState<FormState>('idle');
  const doneRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (state === 'sent') doneRef.current?.focus();
  }, [state]);

  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const data = Object.fromEntries(new FormData(e.currentTarget));
    setState('sending');
    try {
      const res = await fetch(FORM_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({
          ...data,
          _subject: `New enquiry from ${data.name || 'the website'}`,
          _template: 'table',
        }),
      });
      const body = await res.json().catch(() => ({}));
      setState(res.ok && String(body.success) === 'true' ? 'sent' : 'error');
    } catch {
      setState('error');
    }
  }

  if (state === 'sent') {
    return (
      <div className="form form--done" ref={doneRef} tabIndex={-1} role="status">
        <h3>Thanks, that's sent.</h3>
        <p>I'll reply to the email you gave, usually within a day or two.</p>
      </div>
    );
  }

  return (
    <form className="form" onSubmit={submit} aria-label="Send Kian a message">
      <div className="form__row">
        <label htmlFor="cf-name">Your name</label>
        <input id="cf-name" name="name" type="text" autoComplete="name" required />
      </div>
      <div className="form__row">
        <label htmlFor="cf-email">Email</label>
        <input id="cf-email" name="email" type="email" autoComplete="email" required />
      </div>
      <div className="form__row">
        <label htmlFor="cf-business">
          Business <span>(optional)</span>
        </label>
        <input id="cf-business" name="business" type="text" autoComplete="organization" />
      </div>
      <div className="form__row">
        <label htmlFor="cf-message">What do you have in mind?</label>
        <textarea id="cf-message" name="message" rows={5} required />
      </div>
      {/* Bots fill every field; people never see this one. */}
      <input className="form__honey" type="text" name="_honey" tabIndex={-1} autoComplete="off" aria-hidden="true" />
      <div className="form__foot">
        <button className="btn btn--amber" type="submit" disabled={state === 'sending'}>
          {state === 'sending' ? 'Sending…' : 'Send message'}
          <Arrow />
        </button>
        <p className="form__error" role="alert">
          {state === 'error' && (
            <>
              That didn't send. Please email me at <a href={mailto}>{EMAIL}</a> instead.
            </>
          )}
        </p>
      </div>
    </form>
  );
}

